diff --git a/src/knownhost.c b/src/knownhost.c
index 2bd41de..7aa73da 100644
--- a/src/knownhost.c
+++ b/src/knownhost.c
@@ -419,6 +419,15 @@ static int knownhost_parse_ipv4(const char *src, const char *end,
     return 1;
 }

+static int knownhost_ipv6_append(unsigned short *words, size_t *count,
+                                 unsigned int value)
+{
+    if(*count >= 8)
+        return 0;
+    words[(*count)++] = (unsigned short)value;
+    return 1;
+}
+
 static int knownhost_parse_ipv6(const char *src, size_t len,
                                 unsigned char result[16])
 {
@@ -458,20 +467,22 @@ static int knownhost_parse_ipv6(const char *src, size_t len,
         if(p < end && *p == '.') {
             unsigned char ipv4[4];

-            if(count > 6 || !knownhost_parse_ipv4(part, end, ipv4))
+            if(!knownhost_parse_ipv4(part, end, ipv4))
                 return 0;

-            words[count++] =
-                (unsigned short)(((unsigned int)ipv4[0] << 8) | ipv4[1]);
-            words[count++] =
-                (unsigned short)(((unsigned int)ipv4[2] << 8) | ipv4[3]);
+            if(!knownhost_ipv6_append(words, &count,
+                                      ((unsigned int)ipv4[0] << 8) | ipv4[1]) ||
+               !knownhost_ipv6_append(words, &count,
+                                      ((unsigned int)ipv4[2] << 8) | ipv4[3]))
+                return 0;
             break;
         }

-        if(!digits || count >= 8)
+        if(!digits)
             return 0;

-        words[count++] = (unsigned short)value;
+        if(!knownhost_ipv6_append(words, &count, value))
+            return 0;

         if(p == end)
             break;

